import { Injectable } from '@angular/core';
import { finalFeedData, PageParsedItem } from '../../interfaces/feed-display.interface';
import { feeds } from '../../interfaces/feed.interface';

@Injectable({
  providedIn: 'root'
})
export class FeedUtilityService {


  public convertAsciiToVisibleString(asciiArray: number[]): string {
    try {
      if (!Array.isArray(asciiArray)) return '';
      return asciiArray.map(code => {
        try {
          if (code === 17) return '&emsp;';
          return String.fromCharCode(code ?? 0);
        } catch {
          return ''; // skip invalid code
        }
      }).join('');
    } catch {
      return '';
    }
  }

  public parseFeedLineData(rowData: PageParsedItem[]): finalFeedData[] {
    try {
      if (!Array.isArray(rowData)) return [];

      return rowData
        .filter(e => e)
        .map(item => {
          try {
            const asciiArr = Array.isArray(item?.[1]) ? item[1] : [];
            return {
              time: item?.[0] ?? '00:00:00:00',
              // asciiValue: asciiArr,
              lines: [this.convertAsciiToVisibleString(asciiArr)],
              lineIndex: item?.[2] ?? 0,
              formate: item?.[3] ?? 'FL',
              oPage: item?.[4] ?? 0,
              oLine: item?.[5] ?? 0,
              unicid: String(item?.[6] ?? '0'),
              links: Array.isArray(item?.[7]) ? item[7] : []
            };
          } catch {
            return this.blankLine();
          }
        }).filter(a => a.lineIndex > -1);
    } catch {
      return [];
    }
  }



  timeToFram(timestamp: string, isWithFram?: boolean) {
    if (!timestamp) return '';
    const [hours, minutes, seconds, frames] = timestamp.split(':').map(Number);
    return ((hours * 3600 + minutes * 60 + seconds) * 30) + (isWithFram ? frames : 0);
  }


  blankLine() {
    return {
      time: '00:00:00:00',
      // asciiValue: [],
      lines: [''],
      lineIndex: 0,
      formate: 'FL',
      oPage: 0,
      oLine: 0,
      unicid: '0',
      links: []
    }
  }


  blankPage(page: number): feeds {
    return {
      page: page,
      msg: page,
      data: []
    }; //, annotations: [], hyperlinks: []
  }

  sortArray(array) {
    return array.sort((a, b) => {
      const frameA: any = this.timeToFram(a?.time, true);
      const frameB: any = this.timeToFram(b?.time, true);
      if (frameA !== frameB) return frameA - frameB;
      const valA2 = a?.unicid ?? 0;
      const valB2 = b?.unicid ?? 0;
      if (valA2 !== valB2) return valA2 - valB2;
      return 0;
    });
  }





  removeTimestampsInRange(timestamps, range) {
    const [startRange, endRange] = range.map(a => a = this.timeToFram(a, true));
    const sInd = timestamps.findIndex(({ time }) => {
      const currentFrame = this.timeToFram(time, true);
      return currentFrame >= startRange && currentFrame <= endRange;
    })
    const lInd = timestamps.findLastIndex(({ time }) => {
      const currentFrame = this.timeToFram(time, true);
      return currentFrame >= startRange && currentFrame <= endRange;
    })
    return timestamps.filter(({ time }, index) => {
      const currentFrame = this.timeToFram(time, true);
      let isInRange = currentFrame >= startRange && currentFrame <= endRange;
      if (lInd != sInd && lInd == index && currentFrame == endRange) {
        isInRange = false
      }
      if (((lInd - sInd) + 1) > 2 && sInd == index && currentFrame == startRange) {
        try {
          const nextData = timestamps[index + 1]
          if (nextData) {
            const nextTimeRange = this.timeToFram(nextData?.time, true);
            if (nextTimeRange == startRange) {
              isInRange = false
            }
          }
        } catch (error) {
        }
      }

      return !isInRange; //  && sInd != index && lInd != index; //currentFrame < startRange || currentFrame > endRange;
    });
  }




  mapBlankLines(page: feeds) {
    const blankline = this.blankLine();
    page.data = Array.from(page.data, (item, index) => item === undefined ? {
      ...blankline,
      lineIndex: index
    } : item)
  }

 /* mapBlankLines(page: feeds) {
    page.data = page.data.filter(item => item !== undefined);
  }*/

  /** Consistent screen coordinates for any element */
  getScreenCoords(el: HTMLElement): { x: number; y: number } {
    const rect = el.getBoundingClientRect();
    const viewportX = rect.left;
    const viewportY = rect.top;

    // Approximate physical screen coords (best we can do on the web platform)
    const screenX =
      viewportX +
      (window.screenX ?? (window as any).screenLeft ?? 0) +
      (window.visualViewport?.offsetLeft ?? 0);

    const screenY =
      viewportY +
      (window.screenY ?? (window as any).screenTop ?? 0) +
      (window.visualViewport?.offsetTop ?? 0);

    return { x: screenX, y: screenY };
  }
}
