import { Injectable } from '@angular/core';
import { feedAnnotations, qMarksAnnots, rect } from '../../interfaces/annotation.interface';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { HttpClient, HttpParams } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';
import { MarknavService } from '../marknav/marknav.service';

@Injectable()
export class AnnotsService {

    public annotations: feedAnnotations[] = [];

    public annotBox: rect | null = null;

    public qMarks: qMarksAnnots[] = [];



    private applyAnnoptations(): void {
        const originalCount = this.annotations.length;
        if (originalCount > 0) {
             const sample = this.annotations[0];
             console.log('[AnnotDebug] First raw annotation:', sample);
             console.log('[AnnotDebug] Has jCordinates?', !!sample.jCordinates);
             console.log('[AnnotDebug] jCordinates length:', sample.jCordinates?.length);
        }

        this.annotations = this.annotations.filter(a => a.jCordinates?.length);
        this.annotations = [...this.annotations];
        console.log(`AnnotsService: applied annotations. Count: ${this.annotations.length} (Original: ${originalCount})`);
    }

    private applyqMarks(): void {
        this.qMarks = [...this.qMarks];
    }
    constructor(private readonly http: HttpClient, private readonly tost: TostbarService, private readonly markNav: MarknavService) { }

    set(annot: feedAnnotations): void {
        const existsIndex = this.annotations.findIndex(a => a.id === annot.id);
        if (existsIndex === -1) {
            this.annotations.push(annot);
        } else {
            this.annotations[existsIndex] = annot;
        }
        this.applyAnnoptations();
    }

    setAll(annot: feedAnnotations[]): void {
        this.annotations = annot;
        this.applyAnnoptations();
    }

    getAll(): feedAnnotations[] {
        return this.annotations;
    }


    getTemp(): feedAnnotations[] {
        return this.annotations.filter(a => a.isTemp);
    }


    isHaveTempAnnot(): boolean {
        return this.annotations.some(a => a.isTemp);
    }

    delete(id: string): void {
        this.annotations = this.annotations.filter(a => a.id !== id);
        this.applyAnnoptations();
    }


    removeTemp(): void {
        this.annotations = this.annotations.filter(a => !a.isTemp);
        this.applyAnnoptations();
    }

    clearAll(): void {
        this.annotations = [];
        this.annotBox = null;
        this.qMarks = [];
        this.applyAnnoptations();
        this.applyqMarks();
    }

    enableAnnotBox(position: rect): void {
        try {
            position.y = position.y - 150;
        } catch (error) {
            console.error(error);
        }
        this.annotBox = position;
    }

    setqMark(qMark: qMarksAnnots): void {
        const existsIndex = this.qMarks.findIndex(a => a.nHid === qMark.nHid);
        if (existsIndex === -1) {
            this.qMarks.push(qMark);
        } else {
            this.qMarks[existsIndex] = qMark;
        }
        this.applyqMarks();
    }

    setqMarkAll(qMarks: qMarksAnnots[]): void {
        this.qMarks = qMarks;
        this.applyqMarks();
    }

    getqMarkAll(): qMarksAnnots[] {
        return this.qMarks;
    }

    deleteqMark(nHid: string): void {
        this.qMarks = this.qMarks.filter(a => a.nHid !== nHid);
        this.applyqMarks();
    }

    disableAnnotBox(): void {
        this.annotBox = null;
    }

    isBoxEnabled(): boolean {
        return this.annotBox !== null;
    }

    async fetchAnnotations(nSesid: string, nUserid: string, isTrans: boolean): Promise<void> {
        try {
            console.log('[AnnotDebug] fetchAnnotations called with:', { nSesid, nUserid, isTrans });
            const params = new HttpParams().set('nSessionid', nSesid).set('nUserid', nUserid).set('bTranscript', String(isTrans));
            type FetchAnnotationsResponse = [feedAnnotations[]?, qMarksAnnots[]?, feedAnnotations[]?];

            // /feed/annotations currently returns res[2] (doclinks) as an empty array for the
            // individual-doc / transcript viewer context, so a saved doclink would disappear
            // from the inline feed after reload even though MarkNav still showed it. Source
            // doclinks from /marknav/doclinks (the same endpoint MarkNav uses) and merge them
            // in. Run both calls in parallel to avoid extra latency.
            const [res, doclinks] = await Promise.all([
                firstValueFrom(
                    this.http.get<FetchAnnotationsResponse>(
                        `${environment.cloudUrl2}${environment.realtimeserive}/feed/annotations`, { params }
                    )
                ),
                this.markNav.getDocLinkList(nSesid, nUserid, 'P', null, false, isTrans).catch(() => [] as any[])
            ]);

            const annots: feedAnnotations[] = [];
            console.log('fetchAnnotations: Response from server:', res); // Debug Log
            // Q Facts ,facts
            if (res[0]?.length) {
                // Diagnostic — print first/last line of every fact so we can tell at
                // a glance whether the backend returned transferred or draft coords.
                console.log('[AnnotDebug] Fact coord summary:', res[0].map((a: any) => ({
                    id: a.id?.slice(0, 8),
                    cType: a.cType,
                    color: a.color,
                    firstL: a.jCordinates?.[0]?.l,
                    firstP: a.jCordinates?.[0]?.p,
                    firstT: a.jCordinates?.[0]?.t,
                    lastL: a.jCordinates?.[a.jCordinates.length - 1]?.l,
                    lastP: a.jCordinates?.[a.jCordinates.length - 1]?.p,
                })));
                annots.push(...res[0]);
            }
            // rhighlights
            if (res[1]?.length) {
                this.setqMarkAll(res[1]);
            }
            // doc links — prefer payload from /feed/annotations when populated, otherwise fall
            // back to /marknav/doclinks. Coerce cType to 'D' (saveDoc persists 'S' or 'M') so
            // the annotation-layer renders them as DocLinks.
            if (res[2]?.length) {
                annots.push(...res[2]);
            } else if (doclinks?.length) {
                const mapped: feedAnnotations[] = doclinks
                    .filter(d => d?.jCordinates?.length)
                    .map(d => ({
                        id: d.nDocid,
                        cType: 'D',
                        jCordinates: d.jCordinates,
                        color: d.color || d.cColor,
                        nLine: d.nLine,
                        nPage: d.nPage,
                        nColorid: d.nColorid
                    }));
                if (mapped.length) annots.push(...mapped);
            }
            if (annots.length) {
                this.setAll(annots);
            }

        } catch (error: unknown) {
            const msg = ErrorHandlerUtil.getErrorMessage(error);
            this.tost.error(msg && msg !== 'Unknown error' ? msg : 'Failed to fetch annotations');
        }
    }

}