import { BehaviorSubject } from "rxjs";
import { feeds } from "../../interfaces/feed.interface";
import { finalFeedData, liveFeedPage, refreshFeedPage } from "../../interfaces/feed-display.interface";
import { FeedUtilityService } from "../feed-utility/feed-utility.service";

export class refreshHandler {

    // REFRESH Nots
    refreshingEnalbed: boolean;
    refreshTimeout: any;
    enableRefresh = () => {
        try {
            clearTimeout(this.refreshTimeout)
        } catch (error) {
        }
        this.refreshingEnalbed = true;
    }

    disableRefresh = () => {
        try {
            clearTimeout(this.refreshTimeout)
        } catch (error) {
        }
        this.refreshTimeout = setTimeout(() => {
            this.refreshingEnalbed = false;
        }, 400);
    }

    constructor(protected feedUtility: FeedUtilityService) {
    }

    protected getFeedSubject(): BehaviorSubject<feeds[]> {
        return null;
    }


    protected getActiveFeedSubject(): BehaviorSubject<finalFeedData[]> {
        return null;
    }

    protected getSessionLines(): number {
        return null;
    }

    async appendRefreshFeed(res: refreshFeedPage): Promise<void> {
        this.enableRefresh();
        try {
            const lines = this.getSessionLines();
            const { start, end, newLines } = res;
            const feedSubject: BehaviorSubject<feeds[]> = this.getFeedSubject();
            const currentArray = feedSubject.getValue();
            const newData = [];
            if (currentArray.length) {
                const flatData = this.feedUtility.sortArray(currentArray.map((a) => a.data).flat());
                newData.push(...this.feedUtility.removeTimestampsInRange(flatData, [start, end]));
            }
            if (newLines?.length) {
                const parsedData = this.feedUtility.parseFeedLineData(newLines);
                if (parsedData?.length) {
                    newData.push(...parsedData);
                }
            }
            const finalData = this.feedUtility.sortArray(newData).filter(a => a?.time);
            const totalPagges = Math.floor(finalData.length / (lines)) + 1;
            for (let i = 0; totalPagges > i; i++) {
                if (!currentArray[i]) {
                    currentArray[i] = this.feedUtility.blankPage(i + 1);
                }
                currentArray[i]["data"] = finalData.slice(i * 25, (i + 1) * 25);
                this.feedUtility.mapBlankLines(currentArray[i]);
            }
            feedSubject.next([...currentArray]);


            await this.refreshActiveFeed();

        } catch (error) {
            console.error(error);
        }
        this.disableRefresh();
    }


    async refreshActiveFeed(): Promise<void> {
        const activeFeedSubject = this.getActiveFeedSubject();
        const activeData = activeFeedSubject.getValue();
        const totalLines = activeData?.length;
        if (totalLines > 0) {
            const feedDataSubject = this.getFeedSubject();
            const feedData: feeds[] = feedDataSubject.getValue();
            if (feedData?.length) {
                const { page, data } = feedData[feedData.length - 1];
                const lastData = data.slice(-totalLines)
                activeFeedSubject.next(lastData.map(item => ({ ...item })));
            }
        }
    }

}