import { SocketService } from '../../../core/services/socket/socket.service';
import { feeds } from '../../interfaces/feed.interface';
import { sessionDetail } from '../../interfaces/realtime.interface';
import async from 'async';
import { PageFetchService } from './page-fetch.service';
import { HttpClient } from '@angular/common/http';
import { annotTransferEvent, feedPage, finalFeedData, liveFeedPage, PageParsedItem, refreshFeedPage, transcriptData } from '../../interfaces/feed-display.interface';
import { FeedUtilityService } from '../feed-utility/feed-utility.service';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { AnnotsService } from '../annots/annots.service';
