import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { sessionDetail, activeSessionRes } from '../../interfaces/realtime.interface';
import { CaseDetailResponce } from '../../../adminpanel/interfaces/casebuilder.interface';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';

@Injectable({
  providedIn: 'root'
})
export class RealtimeService {

  constructor(private http: HttpClient) { }

  async getActiveSession(nCaseid: string): Promise<string | null> {
    let params = new HttpParams().set('nCaseid', nCaseid);
    try {

      const res: activeSessionRes = await firstValueFrom(
        this.http.get<activeSessionRes>(
          `${environment.cloudUrl2}${environment.realtimeserive}/session/activesession`, { params: params }
        )
      );

      if (res.msg == 1) {
        return res.nSesid;
      } else {
        return null;
      }

    } catch (error) {
      console.error(error);
      return null;
    }
  }

  async getSessionDetail(nSesid: string, nUserid: string): Promise<sessionDetail | null> {
    let params = new HttpParams().set('nSesid', nSesid).set('nUserid', nUserid);
    try {

      const res: sessionDetail = await firstValueFrom(
        this.http.get<sessionDetail>(
          `${environment.cloudUrl2}${environment.realtimeserive}/session/activesession/detail`, { params: params }
        )
      );
      return res;

    } catch (error) {
      console.error(error);
      return null;
    }
  }





  async getRealtimeDataBySessionId(nSesid: string, nUserid: string, nCaseid: string): Promise<any> {
    let params = new HttpParams().set('nSesid', nSesid);
    params = params.set('nUserid', nUserid);
    params = params.set('nCaseid', nCaseid);
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<any>(
          `${environment.cloudUrl2}${environment.realtimeserive}/session/realtimedatabysesid`,
          { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }

  async getCaseDetail(nCaseid: string): Promise<CaseDetailResponce | null> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<CaseDetailResponce>(
          `${environment.cloudUrl}${environment.coreservice}/case/casedetail`,
          { params: params }
        )
      );
      return res;
    } catch (err: unknown) {
      console.error(`Failed to get case detail: ${ErrorHandlerUtil.getErrorMessage(err)}`);
      return null;
    }
  }

}