// src/app/services/page-fetch.base.ts
import { HttpClient, HttpParams } from '@angular/common/http';
import { BehaviorSubject, Subject, Observable, from, throwError, firstValueFrom } from 'rxjs';
import { concatMap, finalize, takeUntil, catchError, map, retry, timeout, delay } from 'rxjs/operators';


// Optional: keep the token so consumers can configure a global default
import { InjectionToken } from '@angular/core';
import { feedEventType, feedPage, feedResponse, SessionEvent } from '../../interfaces/feed-display.interface';
import { environment } from '../../../../environments/environment';
import { refreshHandler } from './refresh-handler';
import { FeedUtilityService } from '../feed-utility/feed-utility.service';
export const PAGE_BATCH_SIZE = new InjectionToken<number>('PAGE_BATCH_SIZE');

export interface BatchResult {
  // pages: feedPage[];
  response: feedResponse;
  isFirst: boolean;
  isLast: boolean;
}
export class PageFetchService extends refreshHandler {
  protected _isFetching$ = new BehaviorSubject<boolean>(false);
  readonly isFetching$ = this._isFetching$.asObservable();
  private readonly url = (environment.name == 'localdocker') ? environment.realtimelocal : `${environment.cloudUrl2}${environment.realtimeserive}`;
  protected stop$ = new Subject<void>();



  private readonly _events = new Subject<SessionEvent>(); // your payload type
  readonly events$ = this._events.asObservable();

  emit(type: feedEventType, data?) {
    this._events.next({ type, data });
  }

  constructor(
    protected http: HttpClient,
    protected defaultBatchSize = 5,
    protected override feedUtility: FeedUtilityService
  ) {
    super(feedUtility)
  }

  async fetchTotalPages(nSesid: string): Promise<number> {
    const res = await this.fetchTotalPage(nSesid);
    if (res.msg == -1) {
      console.error(res.error || `Failed to fectch total pages of session ${nSesid}`);
    }
    return res?.total || 0

  }


  startFetching(
    nSesid: string,
    isTrans: boolean,
    totalPages: number,
    opts: { batchSize?: number; descending?: boolean; endpoint?: string; abortOnError?: boolean; } = {}
  ): Observable<BatchResult> {  // <-- changed
    const batchSize = opts.batchSize ?? this.defaultBatchSize ?? 5;
    const descending = opts.descending ?? true;
    const endpoint = '/feed/pages/data';
    const abortOnError = opts.abortOnError ?? true;

    this.cancel(true);

    const start = isTrans ? 1 : totalPages;
    const end = 1;
    const batches = this.buildBatches(start, end, batchSize, descending);
    this._isFetching$.next(true);

    return from(batches).pipe(
      takeUntil(this.stop$),
      concatMap((ids, index) =>
        this.fetchBatch(nSesid, isTrans, endpoint, ids).pipe(
          takeUntil(this.stop$),
          map<feedResponse, BatchResult>(batch => ({     // <-- explicit map types (optional but clear)
            response: batch,
            isFirst: index === 0,
            isLast: index === batches.length - 1
          })),
          catchError(err => {
            if (abortOnError) return throwError(() => err);
            console.warn('Batch failed, continuing:', ids, err);
            return from<BatchResult[]>([{
              response: { total: 0, feed: [] },//[] as feedPage[],
              isFirst: index === 0,
              isLast: index === batches.length - 1
            }]);
          })
        )
      ),
      finalize(() => this._isFetching$.next(false))
    );
  }

  cancel(silent = false): void {
    if (!this.stop$.closed) {
      this.stop$.next();
      this.stop$.complete();
    }
    this.stop$ = new Subject<void>();
    if (!silent) this._isFetching$.next(false);
  }

  // ---- helpers -------------------------------------------------------------

  protected fetchBatch(nSesid: string, isTrans: boolean, endpoint: string, ids: number[]): Observable<feedResponse> {
    const params = new HttpParams().set('nSesid', nSesid).set('pages', JSON.stringify(ids)).set('bTranscript', isTrans ? 'true' : 'false');
    const fullUrl = `${this.url}${endpoint}`;
    return this.http.get<feedResponse>(fullUrl, { params }).pipe(
      timeout(10000), // Timeout after 10 seconds
      retry({ count: 3, delay: 1000 }), // Retry 3 times with 1s delay
      map(res => {
        return res;
      }),
      catchError(err => {
        console.error('API_FETCH: Error', err);
        throw err;
      })
    );
  }

  async fetchTotalPage(nSesid: string, retries = 3): Promise<{ msg: 1 | -1, total: number, error?: any }> {
    try {
      const params = new HttpParams().set('nSesid', nSesid);
      const res = await firstValueFrom(
        this.http.get<{ msg: 1 | -1, total: number, error?: any }>(`${this.url}/feed/pages/total`, { params })
      )
      if (res?.msg === -1 && retries > 0) {
        await new Promise(resolve => setTimeout(resolve, 500));
        return this.fetchTotalPage(nSesid, retries - 1);
      }
      return res;
    } catch (error) {
      if (retries > 0) {
         await new Promise(resolve => setTimeout(resolve, 500));
         return this.fetchTotalPage(nSesid, retries - 1);
      }
      return { msg: -1, total: 0, error: error };
    }
  }

  protected buildBatches(start: number, end: number, size: number, descending: boolean): number[][] {
    if (descending && start < end) [start, end] = [end, start];
    if (!descending && start > end) [start, end] = [end, start];

    const ids: number[] = [];
    if (descending) for (let i = start; i >= end; i--) ids.push(i);
    else for (let i = start; i <= end; i++) ids.push(i);

    const out: number[][] = [];
    for (let i = 0; i < ids.length; i += size) out.push(ids.slice(i, i + size));
    return out;
  }
}
