  async historyInsert(history: historyBuilderMdl): Promise<any> {
    try {

      const res = await firstValueFrom(
        this.http.post<historyCommonRes>(
          `${environment.cloudUrl2}${environment.realtimeserive}/marknav/history/insert`, history
        )
      );

      if (res.msg != 1) {
        return { msg: -1, error: res.error };
      }

      return res;
    } catch (error: any) {
      console.error('error', error);
      return { msg: -1, error: error.message };
    }
  }

  async historyDelete(history: historyDeleteMdl): Promise<any> {
    try {
      let params = new HttpParams().set('nUserid', history.nUserid).set('cType', history.cType).set('cTimeFrame', history.cTimeFrame)
      if (history.nSesid) {
        params = params.set('nSesid', history.nSesid);
      }
      else {
        params = params.set('nBundledetailid', history.nBundledetailid);
      }
      const res = await firstValueFrom(
        this.http.delete<historyCommonRes>(
          `${environment.cloudUrl2}${environment.realtimeserive}/marknav/history/delete`, { params: params }
        )
      );

      if (res.msg != 1) {
        return { msg: -1, error: res.error };
      }

      this.toast.success('History deleted successfully');
      return res;
    } catch (error: any) {
      console.error('error', error);
      return { msg: -1, error: error.message };
    }
  }


