import { Injectable } from "@angular/core";
import { annotRefreshData, annotTransferEvent, highlightRefreshData } from "../../interfaces/feed-display.interface";
import { AnnotsService } from "../annots/annots.service";
import { feedAnnotations, qMarksAnnots } from "../../interfaces/annotation.interface";
import { SecureStorageService } from "../../../core/services/storage/secure-storage.service";

@Injectable()
export class annotTrasnferService {

    constructor(private readonly annotService: AnnotsService, private secureStore: SecureStorageService) {

    }

    async handleAnnotTrasnfer(res: annotTransferEvent): Promise<void> {
        try {
            const nUserid: string = await this.secureStore.getUserId();
            const { cType, data } = res;
            if (!data || !data?.length) {
                console.error('No data received on refresh', res);
                return;
            }
            if (cType == 'H') {
                const highlightRefreshData = data as highlightRefreshData[];

                const highlights: qMarksAnnots[] = this.annotService.getqMarkAll();
                let updateRequired = false;
                for (let x of highlightRefreshData) {
                    if (nUserid == x.nUserid) {
                        const obj = highlights.find(a => a.nHid == x.nHid);
                        if (obj) {
                            updateRequired = true;
                            obj.cPageno = Number(x.cPageno);
                            obj.cLineno = Number(x.cLineno);
                            obj.identity = String(x.identity);
                            obj.cTime = x.cTime;
                        }
                    }
                }

                if (updateRequired) {
                    this.annotService.setqMarkAll(highlights);
                }

            } else {

                const annotRefreshData = data as annotRefreshData[];

                const annotations: feedAnnotations[] = this.annotService.getAll();
                let updateRequired = false;
                for (let x of annotRefreshData) {
                    if (nUserid == x.nUserid) {
                        const obj = annotations.find(a => a.id == x.nId);
                        if (obj) {
                            updateRequired = true;
                            obj.jCordinates = x.jCordinates;
                        }
                    }
                }

                if (updateRequired) {
                    this.annotService.setAll(annotations);
                }

            }
        } catch (error) {
            console.error('Error during Transfer', error, res);
        }
    }
}